  1	/**
  2	 * Unit tests for PollingManager.
  3	 *
  4	 * All dependencies (ProjectManager, WorkspaceManager, fetchStatusFn) are
  5	 * replaced with lightweight in-memory mocks so no real git I/O or disk I/O
  6	 * is needed.
  7	 */
  8	import { test } from 'node:test';
  9	import assert from 'node:assert/strict';
 10	import type { AppConfig } from '../../config/config.types.js';
 11	import type { ProjectManager } from '../../models/project/project.manager.js';
 12	import type { WorkspaceManager } from '../../models/workspace/workspace.manager.js';
 13	import type { WorkspaceInfo } from '../../models/workspace/workspace.types.js';
 14	import type { GitStatusInfo } from '../../git/git.types.js';
 15	import { PollingManager } from '../pollingManager.js';
 16	
 17	// ---------------------------------------------------------------------------
 18	// Minimal stubs / factories
 19	// ---------------------------------------------------------------------------
 20	
 21	const BASE_CONFIG: AppConfig = {
 22	    projectsFolder: '/fake/projects',
 23	    storageFolder: '/fake/storage',
 24	    cloneDepth: 50,
 25	    serverPort: 4200,
 26	    gitPollingIntervalSeconds: 30,
 27	};
 28	
 29	function makeStatus(branch = 'main'): GitStatusInfo {
 30	    return {
 31	        currentBranch: branch,
 32	        localCommits: 0,
 33	        unfetchedCommits: 0,
 34	        modifiedFiles: 0,
 35	        lastActivity: '2024-01-01T00:00:00Z',
 36	        hasConflicts: false,
 37	    };
 38	}
 39	
 40	interface MockProject {
 41	    Id: string;
 42	    Repositories: string[];
 43	    Workspaces: Record<string, unknown>;
 44	    [key: string]: unknown;
 45	}
 46	
 47	function makeProjectManager(projects: MockProject[]): ProjectManager {
 48	    return {
 49	        list: () => projects.map((p) => ({ Id: p.Id, Name: p.Id })),
 50	        getById: (id: string) => projects.find((p) => p.Id === id) ?? undefined,
 51	        updateLastActivity: (_id: string, _value: string) => { /* no-op */ },
 52	    } as unknown as ProjectManager;
 53	}
 54	
 55	function makeWorkspaceManager(workspaces: Record<string, WorkspaceInfo | undefined>): WorkspaceManager {
 56	    return {
 57	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
 58	            return workspaces[`${projectId}:${workspaceId}`];
 59	        },
 60	    } as unknown as WorkspaceManager;
 61	}
 62	
 63	/**
 64	 * Returns a mock WorkspaceManager where every (projectId, workspaceId) combo
 65	 * that has the form `<project>:STABLE` is treated as existing.
 66	 */
 67	function makeDefaultWorkspaceManager(): WorkspaceManager {
 68	    return {
 69	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
 70	            if (workspaceId === 'STABLE') {
 71	                return {
 72	                    ProjectID: projectId,
 73	                    WorkspaceID: 'STABLE',
 74	                    Description: '',
 75	                    DateCreated: '',
 76	                    DateModified: '',
 77	                };
 78	            }
 79	            return undefined;
 80	        },
 81	    } as unknown as WorkspaceManager;
 82	}
 83	
 84	// ---------------------------------------------------------------------------
 85	// Helpers
 86	// ---------------------------------------------------------------------------
 87	
 88	/** Waits for a promise to resolve within `ms` milliseconds. */
 89	function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
 90	    return Promise.race([
 91	        promise,
 92	        new Promise<T>((_, reject) =>
 93	            setTimeout(() => reject(new Error(`Timed out after ${ms}ms`)), ms),
 94	        ),
 95	    ]);
 96	}
 97	
 98	// ---------------------------------------------------------------------------
 99	// getStatus — cache reads
100	// ---------------------------------------------------------------------------

101	
102	test('getStatus: returns null before the first poll', () => {
103	    const pm = makeProjectManager([]);
104	    const wm = makeDefaultWorkspaceManager();
105	    const mgr = new PollingManager(BASE_CONFIG, pm, wm);
106	
107	    assert.strictEqual(mgr.getStatus('/fake/projects/proj/STABLE/repo'), null);
108	});
109	
110	test('getStatus: returns the cached value after refreshWorkspace', async () => {
111	    const project = {
112	        Id: 'proj',
113	        Repositories: ['repo'],
114	        Workspaces: { STABLE: {} },
115	    };
116	    const pm = makeProjectManager([project]);
117	    const wm = makeDefaultWorkspaceManager();
118	    const expectedStatus = makeStatus('feature');
119	    const fetchFn = async (_path: string) => expectedStatus;
120	
121	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
122	    await mgr.refreshWorkspace('proj', 'STABLE');
123	
124	    const cached = mgr.getStatus('/fake/projects/proj/STABLE/repo');
125	    assert.deepEqual(cached, expectedStatus);
126	});
127	
128	test('getStatus: returns null for a path that has never been polled', async () => {
129	    const project = {
130	        Id: 'proj',
131	        Repositories: ['repo-a'],
132	        Workspaces: { STABLE: {} },
133	    };
134	    const pm = makeProjectManager([project]);
135	    const wm = makeDefaultWorkspaceManager();
136	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, async () => makeStatus());
137	
138	    await mgr.refreshWorkspace('proj', 'STABLE');
139	    // repo-b was never polled
140	    assert.strictEqual(mgr.getStatus('/fake/projects/proj/STABLE/repo-b'), null);
141	});
142	
143	// ---------------------------------------------------------------------------
144	// refreshWorkspace
145	// ---------------------------------------------------------------------------
146	
147	test('refreshWorkspace: fetches status for every repo in the workspace', async () => {
148	    const project = {
149	        Id: 'my-proj',
150	        Repositories: ['repo-1', 'repo-2'],
151	        Workspaces: { STABLE: {} },
152	    };
153	    const pm = makeProjectManager([project]);
154	    const wm = makeDefaultWorkspaceManager();
155	    const fetched: string[] = [];
156	    const fetchFn = async (p: string) => { fetched.push(p); return makeStatus(); };
157	
158	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
159	    await mgr.refreshWorkspace('my-proj', 'STABLE');
160	
161	    assert.deepEqual(fetched.sort(), [
162	        '/fake/projects/my-proj/STABLE/repo-1',
163	        '/fake/projects/my-proj/STABLE/repo-2',
164	    ].sort());
165	});
166	
167	test('refreshWorkspace: updates the cache with the returned status', async () => {
168	    const project = {
169	        Id: 'p1',
170	        Repositories: ['r1'],
171	        Workspaces: { STABLE: {} },
172	    };
173	    const pm = makeProjectManager([project]);
174	    const wm = makeDefaultWorkspaceManager();
175	    const status1 = makeStatus('main');
176	    const status2 = makeStatus('dev');
177	
178	    let callCount = 0;
179	    const fetchFn = async (_: string) => callCount++ === 0 ? status1 : status2;
180	
181	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
182	
183	    await mgr.refreshWorkspace('p1', 'STABLE');
184	    assert.deepEqual(mgr.getStatus('/fake/projects/p1/STABLE/r1'), status1);
185	
186	    await mgr.refreshWorkspace('p1', 'STABLE');
187	    assert.deepEqual(mgr.getStatus('/fake/projects/p1/STABLE/r1'), status2);
188	});
189	
190	test('refreshWorkspace: resolves even when fetchStatusFn rejects for a repo', async () => {
191	    const project = {
192	        Id: 'proj',
193	        Repositories: ['ok-repo', 'bad-repo'],
194	        Workspaces: { STABLE: {} },
195	    };
196	    const pm = makeProjectManager([project]);
197	    const wm = makeDefaultWorkspaceManager();
198	    const fetchFn = async (p: string) => {
199	        if (p.endsWith('bad-repo')) throw new Error('network error');
200	        return makeStatus();
201	    };
202	
203	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
204	    // Should not reject
205	    await assert.doesNotReject(() => mgr.refreshWorkspace('proj', 'STABLE'));
206	});
207	
208	test('refreshWorkspace: cache for ok-repo is populated when bad-repo fails', async () => {
209	    const project = {
210	        Id: 'proj',
211	        Repositories: ['ok-repo', 'bad-repo'],
212	        Workspaces: { STABLE: {} },
213	    };
214	    const pm = makeProjectManager([project]);
215	    const wm = makeDefaultWorkspaceManager();
216	    const okStatus = makeStatus('main');
217	    const fetchFn = async (p: string) => {
218	        if (p.endsWith('bad-repo')) throw new Error('fail');
219	        return okStatus;
220	    };
221	
222	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
223	    await mgr.refreshWorkspace('proj', 'STABLE');
