398	// ---------------------------------------------------------------------------
399	// restart
400	// ---------------------------------------------------------------------------

101	     * @param intervalSeconds  How often (in seconds) to run a full poll sweep.
102	     */
103	    start(intervalSeconds: number): void {
104	        if (this.intervalHandle !== null) {
105	            return; // already running
106	        }
107	
108	        const intervalMs = intervalSeconds * 1000;
109	
110	        this.intervalHandle = setInterval(() => {
111	            if (this.sweepInProgress) return; // skip overlapping sweeps
112	            this.sweepInProgress = true;
113	            this.runSweep().finally(() => {
114	                this.sweepInProgress = false;
115	            });
116	        }, intervalMs);
117	
118	        // Allow Node.js to exit even if the interval is still active
119	        if (typeof this.intervalHandle.unref === 'function') {
120	            this.intervalHandle.unref();
121	        }
122	    }
123	
124	    /**
125	     * Stops the background polling loop.
126	     *
127	     * Any sweep already in progress continues to completion (its cache writes
128	     * are harmless); no further sweeps will be scheduled after `stop()` returns.
129	     * Calling `stop()` when the loop is not running is a no-op.
130	     */
131	    stop(): void {
132	        if (this.intervalHandle !== null) {
133	            clearInterval(this.intervalHandle);
134	            this.intervalHandle = null;
135	        }
136	    }
137	
138	    /**
139	     * Restarts the background polling loop with a new interval.
140	     *
141	     * Stops the current loop (if running) and immediately starts a new one with
142	     * `intervalSeconds`.  This is the correct way to apply a live interval change
143	     * without creating a new `PollingManager` instance.
144	     *
145	     * @param intervalSeconds  The new polling interval in seconds.
146	     */
147	    restart(intervalSeconds: number): void {
148	        this.stop();
149	        this.start(intervalSeconds);
150	    }
151	
152	    /**
153	     * Returns the most recently cached `GitStatusInfo` for the given absolute
154	     * repo path, or `null` if the repo has not been polled yet.
155	     */
156	    getStatus(repoPath: string): GitStatusInfo | null {
157	        return this.cache.get(repoPath) ?? null;
158	    }
159	
160	    /**
161	     * Fetches live status for every repository in the specified workspace,
162	     * updates the in-memory cache with the results, and resolves when all
163	     * fetches have completed.
164	     *
165	     * Fetches are staggered by `STAGGER_MS` to avoid hammering the network.
166	     * Individual fetch failures are swallowed so that a single unreachable
167	     * repository does not prevent the others from being updated.  When an
168	     * `ErrorLogManager` is configured, failures are logged (with deduplication).
169	     *
170	     * @throws {Error} If the project or workspace does not exist (propagated
171	     *   from `WorkspaceManager`).
172	     */
173	    async refreshWorkspace(projectId: string, workspaceId: string): Promise<void> {
174	        const repoPaths = this.getRepoPaths(projectId, workspaceId);
175	        await this.fetchWithStagger(repoPaths);
176	        this.persistLastActivity();
177	    }
178	
179	    // -------------------------------------------------------------------------
180	    // Private helpers
181	    // -------------------------------------------------------------------------
182	
183	    /**
184	     * Collects the absolute paths of all repositories that belong to the given
185	     * workspace.  The path convention mirrors `WorkspaceOrchestrator.repoPath()`:
186	     *   `{projectsFolder}/{projectId}/{workspaceId}/{repoId}`
187	     */
188	    private getRepoPaths(projectId: string, workspaceId: string): string[] {
189	        const project = this.projectManager.getById(projectId);
190	        if (!project) {
191	            throw new Error(
192	                `PollingManager: project "${projectId}" does not exist.`,
193	            );
194	        }
195	        // Validate the workspace exists
196	        const ws = this.workspaceManager.getById(projectId, workspaceId);
197	        if (!ws) {
198	            throw new Error(
199	                `PollingManager: workspace "${workspaceId}" does not exist in project "${projectId}".`,
200	            );
201	        }
202	
203	        return project.Repositories.map((repoId) =>
204	            path.join(this.config.projectsFolder, projectId, workspaceId, repoId),
205	        );
206	    }
207	
208	    /**
209	     * Collects the absolute paths of every repository in every workspace of
210	     * every project that currently exists in the data store.
211	     */
212	    private getAllRepoPaths(): string[] {
213	        const repoPaths: string[] = [];
214	        for (const entry of this.projectManager.list()) {
215	            const project = this.projectManager.getById(entry.Id);
216	            if (!project) continue;
217	            for (const workspaceId of Object.keys(project.Workspaces)) {
218	                for (const repoId of project.Repositories) {
219	                    repoPaths.push(
220	                        path.join(
221	                            this.config.projectsFolder,
222	                            entry.Id,
223	                            workspaceId,
224	                            repoId,
225	                        ),
226	                    );
227	                }
228	            }
229	        }
230	        return repoPaths;
231	    }
232	
233	    /**
234	     * Iterates the current cache, computes the maximum `lastActivity` ISO
235	     * timestamp for each project, and calls `projectManager.updateLastActivity()`
236	     * for every project that has at least one cached entry with a non-null
237	     * `lastActivity`.
238	     *
239	     * Projects where every cached entry has `null` `lastActivity` are skipped.
240	     * Cache entries whose repo path cannot be parsed by `extractContext()` (i.e.
241	     * the function returns an empty object with no `ProjectId`) are ignored
242	     * silently.
243	     */
244	    private persistLastActivity(): void {
245	        // Build a per-project map of the maximum lastActivity timestamp.
246	        const maxByProject = new Map<string, string>();
247	
248	        for (const [repoPath, status] of this.cache) {
249	            if (status.lastActivity === null) {
250	                continue;
251	            }
252	            const context = extractContext(repoPath, this.config.projectsFolder);
253	            if (!context.ProjectId) {
254	                continue;
255	            }
256	            const projectId = context.ProjectId;
257	            const existing = maxByProject.get(projectId);
258	            if (existing === undefined || status.lastActivity > existing) {
259	                maxByProject.set(projectId, status.lastActivity);
260	            }
261	        }
262	
263	        for (const [projectId, maxTimestamp] of maxByProject) {
264	            this.projectManager.updateLastActivity(projectId, maxTimestamp);
265	        }
266	    }
267	
268	    /**
269	     * Fetches status for each repo path sequentially with a `STAGGER_MS` delay
270	     * between calls.  Errors from individual fetches are caught and, when an
271	     * `ErrorLogManager` is configured, logged at warning severity with
272	     * deduplication — at most one log entry per repo path per sweep-to-sweep
273	     * cycle.  A previously failing repo that recovers is removed from the dedup
274	     * set so that a future failure can produce a new entry.
275	     */
276	    private async fetchWithStagger(repoPaths: string[]): Promise<void> {
277	        for (let i = 0; i < repoPaths.length; i++) {
278	            if (i > 0) {
279	                await delay(STAGGER_MS);
280	            }
281	            const repoPath = repoPaths[i];
282	            try {
283	                const status = await this.fetchStatusFn(repoPath);
284	                this.cache.set(repoPath, status);
285	                // Recovery: clear the dedup flag so the next failure is logged.
286	                this.failedPaths.delete(repoPath);
287	            } catch (err) {
288	                // Log at most one warning per repo path per sweep cycle.
289	                if (this.errorLogManager && !this.failedPaths.has(repoPath)) {
290	                    const context = extractContext(repoPath, this.config.projectsFolder);
291	                    const message = err instanceof Error ? err.message : String(err);
292	                    this.errorLogManager.append({
293	                        Severity: 'warning',
294	                        Source: 'polling',
295	                        Operation: 'status-poll',
296	                        Context: context,
297	                        Message: `Failed to fetch status for repository: ${message}`,
298	                        Details: `Repository path: ${repoPath}`,
299	                    });
300	                    this.failedPaths.add(repoPath);

